css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .completa-fila{display: flex; align-items: center; gap: 9px; font-size: 18px; font-weight: 700; margin-bottom: 9px; flex-wrap: wrap;}
.mz .completa-fila .num-grande{min-width: 64px;}
.mz .completa-fila .pieza-dada{border: 1.5px solid var(--bosque); border-radius: 6px; padding: 4px 12px; background: #f3f3f3;}
.mz .completa-fila .caja-hueco{width: 82px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .completa-fila .mas{font-family: sans-serif;}
.mz .pista-fila{display: flex; align-items: center; gap: 12px; font-size: 15px; font-weight: 600; margin-bottom: 10px;}
.mz .pista-fila .pista{flex: 1; line-height: 1.3;}
.mz .pista-fila .caja-cifra{width: 100px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .unir-grid{display: grid; grid-template-columns: 95px 1fr 150px; gap: 6px 0; align-items: center;}
.mz .unir-grid .u-num{font-size: 20px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 5px 0;}
.mz .unir-grid .u-desc{font-size: 15px; font-weight: 600; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .unir-grid .u-mid{height: 10px;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: wrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 56px; height: 40px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
